import os
from typing import Any, Dict, Iterable, Optional, Union

from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient


REQUIRED_FIELDS = {
    "vendor_name": "VendorName",
    "invoice_id": "InvoiceId",
    "invoice_date": "InvoiceDate",
    "due_date": "DueDate",
    "customer_name": "CustomerName",
    "subtotal": "SubTotal",
    "total_tax": "TotalTax",
    "invoice_total": "InvoiceTotal",
}


def _field_confidence(field: Any) -> Optional[float]:
    confidence = getattr(field, "confidence", None)
    return float(confidence) if confidence is not None else None


def _field_value(field: Any) -> Any:
    if field is None:
        return None
    if getattr(field, "value", None) is not None:
        return field.value
    if getattr(field, "content", None) is not None:
        return field.content
    return None


def _normalize_value(value: Any) -> Any:
    if value is None:
        return None
    if hasattr(value, "isoformat"):
        try:
            return value.isoformat()
        except Exception:
            pass
    if hasattr(value, "amount"):
        currency = getattr(value, "currency_symbol", None) or getattr(value, "currency_code", None)
        return {
            "amount": value.amount,
            "currency": currency,
        }
    if isinstance(value, (str, int, float, bool, list, dict)):
        return value
    return str(value)


def _read_bytes(document: Union[str, bytes, bytearray]) -> bytes:
    if isinstance(document, (bytes, bytearray)):
        return bytes(document)
    if isinstance(document, str):
        with open(document, "rb") as f:
            return f.read()
    raise TypeError("document must be a file path or bytes-like object")


def _validate_required_fields(
    doc_fields: Dict[str, Any],
    required_fields: Dict[str, str],
    min_confidence: float,
) -> Dict[str, Any]:
    extracted: Dict[str, Any] = {}
    missing = []
    low_confidence = []

    for output_name, provider_field_name in required_fields.items():
        field = doc_fields.get(provider_field_name)
        value = _normalize_value(_field_value(field))
        confidence = _field_confidence(field)

        extracted[output_name] = {
            "provider_field": provider_field_name,
            "value": value,
            "confidence": confidence,
            "present": value is not None,
            "valid": value is not None and (confidence is None or confidence >= min_confidence),
        }

        if value is None:
            missing.append(output_name)
        elif confidence is not None and confidence < min_confidence:
            low_confidence.append(
                {
                    "field": output_name,
                    "confidence": confidence,
                    "threshold": min_confidence,
                }
            )

    return {
        "fields": extracted,
        "missing_required_fields": missing,
        "low_confidence_fields": low_confidence,
        "is_valid": not missing and not low_confidence,
    }


def extract_and_validate_invoice(
    document: Union[str, bytes, bytearray],
    min_confidence: float = 0.8,
    required_fields: Optional[Iterable[str]] = None,
    endpoint: Optional[str] = None,
    api_key: Optional[str] = None,
) -> Dict[str, Any]:
    endpoint = endpoint or os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    api_key = api_key or os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(
        endpoint=endpoint,
        credential=AzureKeyCredential(api_key),
    )

    document_bytes = _read_bytes(document)

    poller = client.begin_analyze_document(
        model_id="prebuilt-invoice",
        body=document_bytes,
    )
    result = poller.result()

    documents = getattr(result, "documents", None) or []
    if not documents:
        return {
            "provider": "azure-document-intelligence",
            "model_id": "prebuilt-invoice",
            "is_valid": False,
            "error": "No invoice document was extracted.",
            "fields": {},
            "missing_required_fields": list((required_fields or REQUIRED_FIELDS.keys())),
            "low_confidence_fields": [],
        }

    invoice = documents[0]
    doc_fields = getattr(invoice, "fields", {}) or {}

    if required_fields is None:
        field_map = REQUIRED_FIELDS
    else:
        field_map = {name: REQUIRED_FIELDS[name] for name in required_fields}

    validation = _validate_required_fields(
        doc_fields=doc_fields,
        required_fields=field_map,
        min_confidence=min_confidence,
    )

    return {
        "provider": "azure-document-intelligence",
        "model_id": "prebuilt-invoice",
        "document_type": getattr(invoice, "doc_type", None),
        "document_confidence": getattr(invoice, "confidence", None),
        **validation,
    }
